const rules = $input.all().map(i => i.json);
const sesja = $('Get Sesja').first().json;
const typSesji = (sesja['Typ Sesji'] || '').toLowerCase();

let kat = [];
if (typSesji.includes('ofertowa')) kat = ['ofertowe', 'rolka'];
else if (typSesji.includes('blog') && !typSesji.includes('rolka')) kat = ['tylko blog', 'edukacyjne'];
else if (typSesji.includes('edukacyjn')) kat = ['edukacyjne', 'rolka'];
else kat = ['edukacyjne', 'rolka', 'tylko blog'];

const matching = rules.filter(r => {
  const k = r['Kategoria (Dla jakiego typu)'];
  const arr = Array.isArray(k) ? k : (k ? [k] : []);
  return arr.some(x => kat.some(km => (x || '').toLowerCase().includes(km)));
});

const prio = { 'Krytyczne': 0, 'Wysokie': 1, 'Srednie': 2, 'Niskie': 3 };
matching.sort((a, b) => (prio[a.Priorytet] ?? 99) - (prio[b.Priorytet] ?? 99));

const tresc = (r) => r['Tresc'] || r['Treść'] || '';
const grupy = { Zakaz: [], Nakaz: [], Fakt: [], Styl: [], Meta_SEO: [] };
matching.forEach(r => { const t = r['Typ Wytycznej']; if (grupy[t]) grupy[t].push(r); });

let sys = `# WYTYCZNE M&B Investment (z Airtable, ${matching.length} aktywnych dla '${sesja['Typ Sesji']}')\n\n`;
if (grupy.Zakaz.length) sys += `## ABSOLUTNE ZAKAZY\n${grupy.Zakaz.map(r => `- [${r.Priorytet}] ${r.Nazwa}: ${tresc(r)}`).join('\n')}\n\n`;
if (grupy.Nakaz.length) sys += `## NAKAZY (jezyk korzysci)\n${grupy.Nakaz.map(r => `- [${r.Priorytet}] ${r.Nazwa}: ${tresc(r)}`).join('\n')}\n\n`;
if (grupy.Fakt.length) sys += `## FAKTY (konkretne liczby)\n${grupy.Fakt.map(r => `- [${r.Priorytet}] ${r.Nazwa}: ${tresc(r)}`).join('\n')}\n\n`;
if (grupy.Styl.length) sys += `## STYL\n${grupy.Styl.map(r => `- ${r.Nazwa}: ${tresc(r)}`).join('\n')}\n\n`;

return [{ json: { wytyczne: sys, typSesji: sesja['Typ Sesji'], rulesCount: matching.length } }];

