const aggregated = $('Aggregate Photo URLs').first()?.json || {};
const photos = aggregated.selected_photos || [];

const n_real = photos.length;
const n_scen_real = Math.min(n_real, 5);
const n_scen_ai = 5 - n_scen_real;

