const sesja = $('Get Sesja').first().json;
const dzialka = $('Get Dzialka').first().json;

const wybrane = (sesja['Wybrane Zdjęcia'] || '').split(',').map(s => s.trim()).filter(Boolean);
const lista = (sesja['ListaWszystkichZdjec'] || '').split(',').map(s => s.trim()).filter(Boolean);

const lookup = {};
lista.forEach(entry => {
  const [idx, name, source] = entry.split(':');
  if (idx && name) lookup[idx] = { name, source: source || 'dz' };
});

const dzNum = sesja.NumerDzialki || dzialka['Numer Działki'] || '';
const selected = wybrane
  .map(idx => ({ index: idx, ...lookup[idx] }))
  .filter(s => s.name)
  .map(p => ({
    index: p.index,
    name: p.name,
    source: p.source,
    path: p.source === 'droga'
      ? `/Folder zespołu Mbinvestment.spolka/Pliki do automatyzacji/Działki/Droga dojazdowa/${p.name}`
      : `/Folder zespołu Mbinvestment.spolka/Pliki do automatyzacji/Działki/${dzNum}/${p.name}`
  }));

if (selected.length === 0) {
  return [{ json: { skip: true, photos: [] } }];
}

return selected.map(p => ({ json: p }));

const links = $input.all().map(i => i.json.link).filter(Boolean);
const parsed = $('Parse Selected Photos').all().map(i => i.json);

const photos = parsed.map((p, idx) => ({
  index: p.index,
  name: p.name,
  source: p.source,
  url: links[idx] || ''
})).filter(p => p.url);

return [{ json: { selected_photos: photos } }];

const items = $input.all();                                           
const results = [];                    
const pubId = $('Get Sesja').first().json['Powiązana publikacja'][0];

items.forEach((item, idx) => {
  const b64 = item.json.data?.[0]?.b64_json;
  if (!b64) {
    return;
  }
  const promptIndex = idx + 1;
  const filename = `blog_${pubId}_${promptIndex}.jpg`;

  results.push({
    json: {
      publication_id: pubId,
      prompt_index: promptIndex,
      filename,
      dropbox_path: `/Pliki do
automatyzacji/Wygenerowane(Tymczasowe)/${filename}`
    },
    binary: {
      data: {
        data: b64,
        mimeType: 'image/jpeg',
        fileName: filename
      }
    }
  });
});

if (results.length === 0) {
  throw new Error('Brak b64_json w żadnym item z Generate Blog Image');
}

return results;

const items = $input.all();                                           
const convAll = $('Convert b64 to Binary').all();

return items.map((item, idx) => {
let url = item.json.url || item.json.link
  || item.json?.error?.['shared_link_already_exists']?.metadata?.url || '';
url = url.replace('www.dropbox.com', 'dl.dropboxusercontent.com')
         .replace('?dl=0', '').replace('&dl=0', '');
  const conv = convAll[idx]?.json || convAll[0]?.json || {};

  return {
    json: {
      publication_id: conv.publication_id || '',
      prompt_index: conv.prompt_index || (idx + 1),
      url
    }
  };
});

// Wpięcie: Generate Rolka Edukacyjna → [ten node] → Save Edukacyjna
// GPT edukacyjny emituje root "elements" jako OBIEKT {audio:{src}};
// json2video wymaga TABLICY typowanych elementów. Ten węzeł deterministycznie
// nadpisuje elements poprawną tablicą audio (nie polega na GPT).

const resp = $input.item.json;                       // pełny obiekt OpenAI chat completion
const scenario = JSON.parse(resp.choices[0].message.content);

// URL muzyki z sesji (attachment). Brak muzyki => pole nieobecne/puste.
const arr = $('Get Sesja').first().json['Zasób (from Wybrana Muzyka)'];
const musicUrl = Array.isArray(arr) && arr[0]
  ? (typeof arr[0] === 'string' ? arr[0] : arr[0].url)
  : null;

// Nadpisz root elements poprawną TABLICĄ. Bez muzyki => pusta tablica (żaden 404).
scenario.elements = [];
if (musicUrl) {
  scenario.elements.push({
    type: 'audio',
    src: musicUrl,
    'fade-in': 1.5,
    'fade-out': 2.5,
    loop: -1,
    duration: -2,
    volume: 0.04
  });
}

resp.choices[0].message.content = JSON.stringify(scenario);
return { json: resp };
return $input.all();
